#!/usr/bin/env bash
# one-line patch: bash patch-one-liner.sh [patch [BASE_URL API_KEY MODEL] | unpatch] — uses OPENCODE_GO_* env or literals, bridge until fx native
[ "$1" = "unpatch" ] && mv ~/.local/bin/fx.real ~/.local/bin/fx 2>/dev/null && echo "unpatched: fx → Vercel" && exit 0; [ -n "$2" ] && export OPENCODE_GO_BASE_URL="$1" OPENCODE_GO_API_KEY="$2" OPENCODE_GO_MODEL="$3"; [ -f ~/.local/bin/fx ] && [ ! -f ~/.local/bin/fx.real ] && cp ~/.local/bin/fx ~/.local/bin/fx.real; cp "$(dirname "$0")/fx" ~/.local/bin/fx 2>/dev/null || cp e035-fx-opencode-bridge/bin/fx ~/.local/bin/fx; chmod +x ~/.local/bin/fx; cp "$(dirname "$0")/fx-opencode-proxy.py" ~/.local/bin/fx-opencode-proxy.py 2>/dev/null || cp e035-fx-opencode-bridge/bin/fx-opencode-proxy.py ~/.local/bin/fx-opencode-proxy.py; echo "patched: fx → $OPENCODE_GO_MODEL via $OPENCODE_GO_BASE_URL (proxy 8765) — try: fx status"
